#include <vector>
#include <algorithm>
#include <numeric>
using namespace std;

class Solution {
public:
    int maxTotalSum(vector<int>& nums, int limit, int threshold) {
        vector<int> capped;
        for (int x : nums) {
            if (x > 0) capped.push_back(min(x, threshold));
        }
        sort(capped.rbegin(), capped.rend());
        int ans = 0;
        int take = min((int)capped.size(), limit);
        for (int i = 0; i < take; i++) ans += capped[i];
        return ans;
    }
};

import java.util.*;

class Solution {
    public int maxTotalSum(int[] nums, int limit, int threshold) {
        List<Integer> capped = new ArrayList<>();
        for (int x : nums) {
            if (x > 0) capped.add(Math.min(x, threshold));
        }
        capped.sort(Collections.reverseOrder());
        int ans = 0;
        int take = Math.min(capped.size(), limit);
        for (int i = 0; i < take; i++) ans += capped.get(i);
        return ans;
    }
}

var maxTotalSum = function(nums, limit, threshold) {
    const capped = nums.filter(x => x > 0).map(x => Math.min(x, threshold));
    capped.sort((a, b) => b - a);
    return capped.slice(0, limit).reduce((sum, x) => sum + x, 0);
};
